import { useLang } from '@/context/LanguageContext';
import { SUPPORTED_LANGUAGES } from '@/lib/languages';
export function LanguagePicker() {
  const context = useLang();
  if (!context) return null;
  return <label className="flex flex-wrap items-center justify-end gap-2 text-xs text-ayana-secondary mb-4">
    <span>{context.t('demoUi.language')}</span>
    <select aria-label="Language" value={context.lang} onChange={event => context.setLang(event.target.value)}
      className="max-w-full min-w-0 rounded-lg border border-ayana-line bg-white px-2 py-1.5">
      {SUPPORTED_LANGUAGES.map(language => <option key={language.code} value={language.code}>{language.label}</option>)}
    </select>
  </label>;
}
